FAMILIES.forEach(f=>{
  edgePairs.push(['atlas',`axis_${f.id}`]);
  nodes.filter(n=>n.family===f.id&&n.level===3).forEach(n=>edgePairs.push([`axis_${f.id}`,n.id]));
});

const byId = Object.fromEntries(nodes.map(n=>[n.id,n]));
const family = id => FAMILIES.find(f=>f.id===id);
const connectedEntries = id => edgePairs.filter(e=>e[0]===id||e[1]===id).map(e=>({node:byId[e[0]===id?e[1]:e[0]],type:e[2]||'relación conceptual'}));
const connections = id => connectedEntries(id).map(e=>e.node);
const canvas=document.querySelector('#graph'),ctx=canvas.getContext('2d'),shell=canvas.parentElement;
let W=0,H=0,dpr=1,hover=null,selected=null,activeFamily='all',maxLevel=5,query='',drag=false,movedDuringDrag=false,last={x:0,y:0},camera={x:0,y:0,z:1};

function seedLayout(){
  const groups={}; FAMILIES.forEach((f,i)=>{const angle=i*(Math.PI*2/FAMILIES.length)-.8;groups[f.id]={cx:Math.cos(angle)*340,cy:Math.sin(angle)*275,items:[]};});
  nodes.forEach(n=>groups[n.family].items.push(n));
  Object.values(groups).forEach(g=>g.items.forEach((n,i)=>{if(n.level===2){n.x=g.cx;n.y=g.cy;return;}const a=i/g.items.length*Math.PI*2;const radius=n.level===3?100:(n.level===4?158:210);n.x=g.cx+Math.cos(a)*(radius+14*(i%3));n.y=g.cy+Math.sin(a)*(radius*.75+11*((i+1)%3));}));
  byId.atlas.x=0;byId.atlas.y=0;
}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=shell.clientWidth;H=shell.clientHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
const screen=n=>({x:W/2+camera.x+n.x*camera.z,y:H/2+camera.y+n.y*camera.z});
const visible=n=>n.level<=maxLevel&&(activeFamily==='all'||n.family===activeFamily||n.id==='atlas')&&(!query||(`${n.label} ${n.intro} ${n.tags.join(' ')}`).toLowerCase().includes(query));
function draw(){
  ctx.clearRect(0,0,W,H);ctx.save();
  const related=selected?new Set([selected.id,...connections(selected.id).map(n=>n.id)]):null;
  const visibleNodes=nodes.filter(visible);
  edgePairs.forEach(([a,b,type],i)=>{const A=byId[a],B=byId[b],va=visible(A),vb=visible(B);if(!va||!vb)return;const p=screen(A),q=screen(B),highlight=selected&&(a===selected.id||b===selected.id),evidence=type?.startsWith('EVIDENCIA');ctx.beginPath();ctx.moveTo(p.x,p.y);const bend=((i%5)-2)*8*camera.z;ctx.quadraticCurveTo((p.x+q.x)/2+bend,(p.y+q.y)/2-bend,q.x,q.y);ctx.setLineDash(evidence?[4,4]:[]);ctx.strokeStyle=evidence?'#f1efed':(highlight?family(selected.family).color:(A.family===B.family?family(A.family).color:'#5c526e'));ctx.globalAlpha=selected?(highlight?(evidence?1:.98):.07):(evidence?.48:.3);ctx.lineWidth=(highlight?(evidence?2.8:2.2):(evidence?1.1:.7))*Math.max(.7,camera.z);ctx.stroke();ctx.setLineDash([]);});
  ctx.globalAlpha=1;
  const geometry=new Map();
  visibleNodes.forEach(n=>{const p=screen(n),f=family(n.family),is=n===selected||n===hover,isRelated=!related||related.has(n.id),base=[0,10,7,5.2,4.1,3.2][n.level],r=base*Math.max(.75,Math.min(camera.z,1.35));geometry.set(n.id,{p,r,is,isRelated,f});ctx.globalAlpha=isRelated?1:.15;if(is||n.level<=2){ctx.beginPath();ctx.arc(p.x,p.y,r+(n.level===2?10:12),0,Math.PI*2);ctx.strokeStyle=f.color;ctx.globalAlpha=is?.75:(isRelated?.22:.07);ctx.lineWidth=is?1.7:1;ctx.stroke();}ctx.globalAlpha=isRelated?1:.15;ctx.fillStyle=n.level===2?f.color:'#19181f';ctx.strokeStyle=f.color;ctx.lineWidth=is?3:(n.level<=2?2:1.4);ctx.fillRect(p.x-r,p.y-r,r*2,r*2);ctx.strokeRect(p.x-r,p.y-r,r*2,r*2);ctx.globalAlpha=1;});

  const occupied=visibleNodes.map(n=>{const {p,r}=geometry.get(n.id);return{x:p.x-r-3,y:p.y-r-3,w:r*2+6,h:r*2+6};});
  const overlap=(a,b)=>Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x))*Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));
  [...visibleNodes].sort((a,b)=>(a===selected?-1:b===selected?1:a.level-b.level)).forEach(n=>{
    const {p,r,is,isRelated,f}=geometry.get(n.id),size=[0,11,9.5,7.5,6.8,6.2][n.level],label=n.label.toUpperCase();ctx.font=`${size}px DM Mono`;const tw=ctx.measureText(label).width,pad=3;
    const candidates=[
      {x:p.x-tw/2-pad,y:p.y+r+5,w:tw+pad*2,h:size+5},
      {x:p.x-tw/2-pad,y:p.y-r-size-8,w:tw+pad*2,h:size+5},
      {x:p.x+r+7,y:p.y-size/2-2,w:tw+pad*2,h:size+5},
      {x:p.x-r-tw-pad*2-7,y:p.y-size/2-2,w:tw+pad*2,h:size+5},
      {x:p.x-tw/2-pad,y:p.y+r+18,w:tw+pad*2,h:size+5},
      {x:p.x-tw/2-pad,y:p.y-r-size-21,w:tw+pad*2,h:size+5}
    ];
    candidates.forEach(c=>{c.x=Math.max(3,Math.min(W-c.w-3,c.x));c.y=Math.max(3,Math.min(H-c.h-3,c.y));c.score=occupied.reduce((sum,o)=>sum+overlap(c,o),0);});
    const box=candidates.sort((a,b)=>a.score-b.score)[0];occupied.push(box);const tx=box.x+box.w/2,ty=box.y+box.h-3;
    if(Math.hypot(tx-p.x,ty-p.y)>r+18){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(tx,box.y+box.h/2);ctx.strokeStyle=f.color;ctx.globalAlpha=isRelated?.22:.06;ctx.lineWidth=.6;ctx.stroke();}
    ctx.textAlign='center';if(is){ctx.globalAlpha=.96;ctx.fillStyle='#f1efed';ctx.fillRect(box.x,box.y,box.w,box.h);ctx.fillStyle='#18171d';ctx.fillText(label,tx,ty);}else{ctx.globalAlpha=isRelated?(n.level<=2?.92:.68):.1;ctx.lineWidth=2.5;ctx.strokeStyle='#19181f';ctx.strokeText(label,tx,ty);ctx.fillStyle=n.level<=2?'#d5d1d8':'#aaa6b0';ctx.fillText(label,tx,ty);}ctx.globalAlpha=1;
  });
  ctx.restore();
}
function hit(x,y){return nodes.filter(visible).reverse().find(n=>{const p=screen(n);return Math.hypot(x-p.x,y-p.y)<18;});}
function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;drag=true;movedDuringDrag=false;last=pointerPos(e);canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const p=pointerPos(e);if(drag){const dx=p.x-last.x,dy=p.y-last.y;if(Math.hypot(dx,dy)>1)movedDuringDrag=true;camera.x+=dx;camera.y+=dy;last=p;draw();return;}hover=hit(p.x,p.y)||null;canvas.style.cursor=hover?'pointer':'grab';const tip=document.querySelector('#tooltip');if(hover){tip.textContent=hover.label;tip.style.display='block';tip.style.left=`${p.x+14}px`;tip.style.top=`${p.y+12}px`;}else tip.style.display='none';draw();});
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='touch')return;const p=pointerPos(e);drag=false;if(!movedDuringDrag){const n=hit(p.x,p.y);if(n)showDetail(n);}});
canvas.addEventListener('pointercancel',()=>{drag=false;movedDuringDrag=false;});
canvas.addEventListener('pointerleave',()=>{drag=false;hover=null;document.querySelector('#tooltip').style.display='none';draw();});
canvas.addEventListener('wheel',e=>{e.preventDefault();const p=pointerPos(e),old=camera.z,next=Math.max(.48,Math.min(2.2,old*Math.exp(-e.deltaY*.001)));camera.x=p.x-W/2-(p.x-W/2-camera.x)*(next/old);camera.y=p.y-H/2-(p.y-H/2-camera.y)*(next/old);camera.z=next;draw();},{passive:false});

// Respaldo táctil para navegadores móviles que reservan el gesto de arrastre.
let touchGesture=null;
const touchPoint=(t,r)=>({x:t.clientX-r.left,y:t.clientY-r.top});
const touchDistance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const touchMiddle=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});
canvas.addEventListener('touchstart',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),pts=[...e.touches].map(t=>touchPoint(t,r));if(pts.length===1)touchGesture={mode:'pan',last:pts[0],moved:false};else if(pts.length>=2)touchGesture={mode:'pinch',lastMid:touchMiddle(pts[0],pts[1]),lastDist:touchDistance(pts[0],pts[1])};},{passive:false});
canvas.addEventListener('touchmove',e=>{e.preventDefault();if(!touchGesture)return;const r=canvas.getBoundingClientRect(),pts=[...e.touches].map(t=>touchPoint(t,r));if(pts.length===1&&touchGesture.mode==='pan'){const p=pts[0],dx=p.x-touchGesture.last.x,dy=p.y-touchGesture.last.y;if(Math.hypot(dx,dy)>1)touchGesture.moved=true;camera.x+=dx;camera.y+=dy;touchGesture.last=p;draw();}else if(pts.length>=2){const mid=touchMiddle(pts[0],pts[1]),dist=touchDistance(pts[0],pts[1]);if(touchGesture.mode!=='pinch')touchGesture={mode:'pinch',lastMid:mid,lastDist:dist};const old=camera.z,next=Math.max(.4,Math.min(2.4,old*(dist/touchGesture.lastDist)));camera.x+=mid.x-touchGesture.lastMid.x;camera.y+=mid.y-touchGesture.lastMid.y;camera.x=mid.x-W/2-(mid.x-W/2-camera.x)*(next/old);camera.y=mid.y-H/2-(mid.y-H/2-camera.y)*(next/old);camera.z=next;touchGesture.lastMid=mid;touchGesture.lastDist=dist;draw();}},{passive:false});
canvas.addEventListener('touchend',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),ended=touchGesture;if(e.touches.length===1){touchGesture={mode:'pan',last:touchPoint(e.touches[0],r),moved:true};}else{touchGesture=null;if(ended?.mode==='pan'&&!ended.moved&&e.changedTouches[0]){const p=touchPoint(e.changedTouches[0],r),n=hit(p.x,p.y);if(n)showDetail(n);}}},{passive:false});
canvas.addEventListener('touchcancel',()=>{touchGesture=null;},{passive:true});

function showDetail(n){
  selected=n;const f=family(n.family),entries=connectedEntries(n.id),links=entries.map(e=>e.node);
  const direct=n.sources||[],seen=new Set(direct.map(s=>s[1]));
  const relatedSources=links.flatMap(x=>(x.sources||[]).map(s=>[`${s[0]} · vía ${x.label}`,s[1]])).filter(s=>!seen.has(s[1])&&seen.add(s[1])).slice(0,4);
  const profile=PROFILES[n.id];
  const profileBlock=profile?`<div class="detail-block algorithm-profile"><h3>FICHA DEL ALGORITMO</h3><dl><div><dt>QUÉ DETECTA</dt><dd>${profile.scope}</dd></div><div><dt>ENTRADA / SENSOR</dt><dd>${profile.input}</dd></div><div><dt>ESTRUCTURA</dt><dd>${profile.structure}</dd></div><div><dt>DESPLIEGUE</dt><dd>${profile.deployment}</dd></div><div><dt>EVIDENCIA ADVERSARIAL</dt><dd>${profile.adversarial}</dd></div></dl></div>`:'';
  const sourceBlock=(direct.length||relatedSources.length)?`<div class="detail-block" style="--node-color:${f.color}">${direct.length?`<h3>FUENTES DIRECTAS</h3>${direct.map(s=>`<a class="source-link" href="${s[1]}" target="_blank" rel="noreferrer">${s[0]}</a>`).join('')}`:''}${relatedSources.length?`<h3 class="related-heading">BIBLIOGRAFÍA RELACIONADA</h3>${relatedSources.map(s=>`<a class="source-link" href="${s[1]}" target="_blank" rel="noreferrer">${s[0]}</a>`).join('')}`:''}</div>`:'';
  const hasEvidence=entries.some(e=>e.type.startsWith('EVIDENCIA'));
  document.querySelector('#detailContent').innerHTML=`<div class="node-code" style="--node-color:${f.color}">NIVEL ${String(n.level).padStart(2,'0')} — ${LEVELS[n.level-1].name.toUpperCase()}</div><h2>${n.label}</h2>${n.date?`<span class="node-date">${n.date}</span>`:''}<p class="detail-intro">${n.intro}</p>${profileBlock}<div class="detail-block"><h3>FAMILIA / ETIQUETAS</h3><div class="tags"><span class="tag">${f.name}</span>${n.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></div><div class="detail-block"><h3>INTERSECCIONES / ${entries.length}</h3>${hasEvidence?'<p class="evidence-key">EVIDENCIA = combinación evaluada en la fuente del método.</p>':''}<ul class="connections">${entries.map(({node:x,type})=>`<li><button data-node="${x.id}"><span>${x.label}<small class="relation-label ${type.startsWith('EVIDENCIA')?'verified':''}">${type}</small></span><span>→</span></button></li>`).join('')}</ul></div>${sourceBlock}`;
  document.querySelector('#detailPanel').classList.add('open');document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>showDetail(byId[b.dataset.node]));draw();
}
function reset(){camera={x:0,y:0,z:Math.min(1,Math.max(.4,Math.min((W-70)/1050,(H-70)/820)))};selected=null;document.querySelector('#detailPanel').classList.remove('open');draw();}
function buildFilters(){const root=document.querySelector('#filters');const all=[{id:'all',name:'Vista completa',color:'#f1efed'},...FAMILIES];root.innerHTML=all.map((f,i)=>`<button class="filter ${i===0?'active':''}" data-family="${f.id}" style="--family:${f.color}"><span class="num">${String(i).padStart(2,'0')}</span><span class="name">${f.name}</span><span class="count">${f.id==='all'?nodes.length:nodes.filter(n=>n.family===f.id).length}</span></button>`).join('');root.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeFamily=b.dataset.family;root.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));draw();});}
document.querySelector('#searchInput').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();draw();});
document.querySelector('#depthRange').addEventListener('input',e=>{maxLevel=Number(e.target.value);document.querySelector('#depthValue').value=String(maxLevel).padStart(2,'0');if(selected&&!visible(selected)){selected=null;document.querySelector('#detailPanel').classList.remove('open');}document.querySelector('#nodeCount').textContent=`${nodes.filter(visible).length} NODOS`;draw();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'){e.preventDefault();document.querySelector('#searchInput').focus();}if(e.key==='Escape'){document.querySelector('#detailPanel').classList.remove('open');document.querySelector('#aboutModal').hidden=true;}});
document.querySelector('#resetBtn').onclick=reset;document.querySelector('.brand').onclick=e=>{e.preventDefault();reset();};document.querySelector('#closePanel').onclick=()=>{selected=null;document.querySelector('#detailPanel').classList.remove('open');draw();};
const modal=document.querySelector('#aboutModal');document.querySelector('#aboutBtn').onclick=()=>modal.hidden=false;document.querySelector('#closeAbout').onclick=()=>modal.hidden=true;modal.onclick=e=>{if(e.target===modal)modal.hidden=true;};
const main=document.querySelector('main'),sidebar=document.querySelector('.sidebar'),sidebarToggle=document.querySelector('#mobileInfo');
document.querySelector('#closeSidebar').onclick=()=>{main.classList.add('sidebar-collapsed');sidebar.classList.remove('open');setTimeout(resize,290);};
sidebarToggle.onclick=()=>{if(main.classList.contains('sidebar-collapsed')){main.classList.remove('sidebar-collapsed');setTimeout(resize,290);}else sidebar.classList.toggle('open');};
document.querySelector('#nodeCount').textContent=`${nodes.length} NODOS`;window.addEventListener('resize',resize);
seedLayout();buildFilters();resize();reset();
